# ============================================================
#  wolfXsms Modal System - setup-modals.ps1
#  Run inside wolfXsms folder: .\setup-modals.ps1
# ============================================================

Write-Host ""
Write-Host "  Installing modal system..." -ForegroundColor Yellow
Write-Host ""

New-Item -ItemType Directory -Force -Path "$PSScriptRoot\src\context" | Out-Null

# ModalContext.tsx
$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes("$PSScriptRoot\src\context\ModalContext.tsx", $bytes)
Write-Host "  [OK] src\context\ModalContext.tsx" -ForegroundColor Green

# Logs.tsx
$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes("$PSScriptRoot\src\pages\Logs.tsx", $bytes)
Write-Host "  [OK] src\pages\Logs.tsx" -ForegroundColor Green

# ApiKeys.tsx
$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes("$PSScriptRoot\src\pages\ApiKeys.tsx", $bytes)
Write-Host "  [OK] src\pages\ApiKeys.tsx" -ForegroundColor Green

# Simulator.tsx
$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes("$PSScriptRoot\src\pages\Simulator.tsx", $bytes)
Write-Host "  [OK] src\pages\Simulator.tsx" -ForegroundColor Green

# App.tsx
$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes("$PSScriptRoot\src\App.tsx", $bytes)
Write-Host "  [OK] src\App.tsx" -ForegroundColor Green

Write-Host ""
Write-Host "  Modal system installed!" -ForegroundColor Cyan
Write-Host "  Run: npm run dev" -ForegroundColor Yellow
Write-Host ""